      const match = output.match(/@(\w{8})/);
      expect(match).toBeTruthy();
      const ulidPrefix = match![1];

      kspec(`meta set @${ulidPrefix} --name "Updated via ULID"`, tempDir);

      const agent = kspecJson<any>('meta get @ulid-ref', tempDir);
