      expect(output).toContain("meta_ref '@invalid-workflow' not found");
    } catch (e: any) {
      const stdout = e.message || '';
      expect(stdout).toContain("meta_ref '@invalid-workflow' not found");
    }
  });
});

describe('Integration: meta mutation commands', () => {
